PROGRESS_LINE_PATTERN = re.compile(r"^\[\d+/\d+\] \(\d+%\): (.+)$")
PROGRESS_TOOK_PATTERN = re.compile(r"^(.*) took [0-9]+(?:\.[0-9]+)?s$")
# Header of a structured failure block in the unittest FAILURES SUMMARY, e.g.
# "3. test/sql/foo.test:42" followed by a line of '=' separators.
STRUCTURED_HEADER_PATTERN = re.compile(r"^(\d+)\.\s+(.+):(\d+)$")
