def strip_ansi(text: str):
    return ANSI_ESCAPE_PATTERN.sub("", text)


def format_timeout_seconds(value: float):
    return str(int(value)) if float(value).is_integer() else str(value)


def parse_progress_lines(lines):
    # Returns (started, completed): the ordered list of test paths that were only
    # announced (no "took" suffix) and the set of paths that reported completion.
    started = []
    completed = set()
    for line in lines:
        match = PROGRESS_LINE_PATTERN.match(line.strip())
        if not match:
            continue
        rest = match.group(1)
        took_match = PROGRESS_TOOK_PATTERN.match(rest)
        if took_match:
            completed.add(took_match.group(1))
        else:
            started.append(rest)
    return started, completed


def last_started_test(lines, batch):
    started, _ = parse_progress_lines(lines)
    if started:
        return started[-1]
    return batch[-1] if batch else None


def identify_timed_out_test(stdout: str, batch):
    lines = strip_ansi(stdout).splitlines()
    started, completed = parse_progress_lines(lines)
    if started or completed:
        for test in batch:
            if test not in completed:
                return test
    return batch[-1] if batch else None


def find_structured_block(stderr: str):
    # Locate the first structured failure header ("N. <path>:<line>") that is
    # immediately followed by a line of '=' separators. Returns the ANSI-stripped
    # lines together with the header index, test path and line number.
    lines = strip_ansi(stderr).splitlines()
    for idx, line in enumerate(lines):
        match = STRUCTURED_HEADER_PATTERN.match(line.strip())
        if not match:
            continue
        separator = lines[idx + 1].strip() if idx + 1 < len(lines) else ""
        if separator and set(separator) == {"="}:
            return lines, idx, match.group(2), int(match.group(3))
    return None


def extract_structured_block_content(lines, header_idx: int):
    content = []
    for line in lines[header_idx:]:
        if line.lstrip().startswith("~~~"):
            break
        content.append(line)
    while content and not content[-1].strip():
        content.pop()
    while content and not content[0].strip():
        content.pop(0)
    return content


