    # Extract (expected, actual, description) from a "Wrong result in query!" block.
    # The value line has the form "<actual> <> <expected>" and directly follows the
    # "Mismatch on row ..." description line.
    for idx, line in enumerate(lines):
        stripped = line.strip()
        if not stripped.startswith("Mismatch on row"):
            continue
        for value_line in lines[idx + 1 :]:
            if " <> " in value_line:
