        message = []
        cursor += 1
        while cursor < len(stdout_lines) and stdout_lines[cursor].strip():
            if stdout_lines[cursor].lstrip().startswith("~~~"):
                break
            message.append(stdout_lines[cursor].strip())
            cursor += 1
        return message
