def render_test_snippet(test_name: str, line_number: int):
    with open(test_name, "r", encoding="utf8") as f:
        raw_lines = f.read().splitlines()
    if not raw_lines:
        return []
    target = line_number - 1
    if target < 0 or target >= len(raw_lines):
        return []

    # Expand the window backward/forward to the nearest surrounding blank lines.
    start = target
    while start > 0 and raw_lines[start - 1].strip():
        start -= 1
    end = target
    while end + 1 < len(raw_lines) and raw_lines[end + 1].strip():
        end += 1

    window = list(range(start, end + 1))
    while window and not raw_lines[window[0]].strip():
        window.pop(0)
    while window and not raw_lines[window[-1]].strip():
        window.pop()
    if not window:
        return []

    width = len(str(window[-1] + 1))
    snippet = []
    for idx in window:
        number = str(idx + 1).rjust(width)
        prefix = "  > " if idx == target else "    "
        snippet.append(f"{prefix}{number}  {raw_lines[idx]}")
